segments.en:
Likutay Halachos – Laws of Interest – Halacha 3

@import url('https://fonts.googleapis.com/css2?family=EB+Garamond:ital,wght@0,400;0,500;0,600;1,400;1,500&family=Cinzel:wght@400;600&display=swap');

:root {

--gold: #b8912a; --gold-light: #d4aa4a; --bg: #faf7f2; --text: #1a1510;

--rule: #c9a84c; --badge-bg: #2c1f0e; --badge-text: #f0d98a;

--verse-color: #3a2a0a; --kt-color: #5a3e10; --note-bg: #f5efe2; --note-border: #c9a84c;

* { box-sizing: border-box; margin: 0; padding: 0; }

body { font-family: 'EB Garamond', Georgia, serif; font-size: 18px; line-height: 1.85; color: var(--text); background: var(--bg); max-width: 780px; margin: 0 auto; padding: 3rem 2rem 5rem; }

h1 { font-family: 'Cinzel', serif; font-size: 1.9rem; font-weight: 600; color: var(--badge-bg); text-align: center; letter-spacing: 0.04em; margin-bottom: 0.3rem; }

h2 { font-family: 'Cinzel', serif; font-size: 1.1rem; font-weight: 400; color: var(--gold); text-align: center; letter-spacing: 0.12em; margin-bottom: 2.5rem; }

.ruling { background: var(--note-bg); border-left: 4px solid var(--note-border); padding: 1rem 1.4rem; margin: 0 0 2.5rem; font-style: italic; font-size: 1.02rem; color: var(--verse-color); }

.sec-header { display: flex; align-items: center; gap: 1rem; margin: 2.4rem 0 1rem; }

.sec-badge { font-family: 'Cinzel', serif; font-size: 0.82rem; font-weight: 600; background: var(--badge-bg); color: var(--badge-text); padding: 0.2rem 0.7rem; letter-spacing: 0.08em; white-space: nowrap; flex-shrink: 0; }

.sec-rule { flex: 1; height: 1px; background: linear-gradient(to right, var(--rule), transparent); }

p { margin-bottom: 1.2rem; text-align: justify; hyphens: auto; }

.v { color: var(--verse-color); font-style: italic; }

.kt { color: var(--kt-color); font-style: italic; }

.aram { color: var(--kt-color); font-style: italic; }

.gloss { font-size: 0.88em; color: #7a6030; font-style: normal; }

.translator-note { background: var(--note-bg); border: 1px solid var(--note-border); padding: 1.2rem 1.6rem; margin-top: 3rem; font-size: 0.92rem; line-height: 1.75; color: #4a3820; }

.colophon { text-align: center; font-family: 'Cinzel', serif; font-size: 1.05rem; color: var(--gold); letter-spacing: 0.15em; margin-top: 3rem; padding-top: 1.5rem; border-top: 1px solid var(--rule); }
